module king_spread(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [127:0] board_packed,\n    output reg [31:0] mirko_spread,\n    output reg [31:0] slavko_spread,\n    output reg done\n);\n\n    localparam [2:0]\n        IDLE        = 3'd0,\n        SCAN        = 3'd1,\n        COMPUTE_M   = 3'd2,\n        CALC_DIST_M = 3'd3,\n        COMPUTE_S   = 3'd4,\n        CALC_DIST_S = 3'd5,\n        DONE        = 3'd6;\n\n    reg [2:0] state;\n    reg [2:0] row_idx, col_idx;\n    reg [4:0] M_count, S_count;\n    reg [7:0] M_x [0:15];\n    reg [7:0] M_y [0:15];\n    reg [7:0] S_x [0:15];\n    reg [7:0] S_y [0:15];\n    reg [4:0] i_idx, j_idx;\n\n    wire [5:0] cell_index = {row_idx, col_idx};\n    wire [6:0] cell_addr = {cell_index, 1'b0};\n    wire [1:0] current_cell = board_packed[cell_addr +: 2];\n\n    wire [7:0] dx = (M_x[i_idx] > M_x[j_idx]) ? (M_x[i_idx] - M_x[j_idx]) : (M_x[j_idx] - M_x[i_idx]);\n    wire [7:0] dy = (M_y[i_idx] > M_y[j_idx]) ? (M_y[i_idx] - M_y[j_idx]) : (M_y[j_idx] - M_y[i_idx]);\n    wire [7:0] dist = (dx > dy) ? dx : dy;\n\n    wire [7:0] dx_s = (S_x[i_idx] > S_x[j_idx]) ? (S_x[i_idx] - S_x[j_idx]) : (S_x[j_idx] - S_x[i_idx]);\n    wire [7:0] dy_s = (S_y[i_idx] > S_y[j_idx]) ? (S_y[i_idx] - S_y[j_idx]) : (S_y[j_idx] - S_y[i_idx]);\n    wire [7:0] dist_s = (dx_s > dy_s) ? dx_s : dy_s;\n\n    integer i;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            mirko_spread <= 32'd0;\n            slavko_spread <= 32'd0;\n            M_count <= 5'd0;\n            S_count <= 5'd0;\n            row_idx <= 3'd0;\n            col_idx <= 3'd0;\n            i_idx <= 5'd0;\n            j_idx <= 5'd0;\n            for (i = 0; i < 16; i = i + 1) begin\n                M_x[i] <= 8'd0;\n                M_y[i] <= 8'd0;\n                S_x[i] <= 8'd0;\n                S_y[i] <= 8'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        mirko_spread <= 32'd0;\n                        slavko_spread <= 32'd0;\n                        M_count <= 5'd0;\n                        S_count <= 5'd0;\n                        row_idx <= 3'd0;\n                        col_idx <= 3'd0;\n                        state <= SCAN;\n                    end\n                end\n                \n                SCAN: begin\n                    if (current_cell == 2'b01 && M_count < 5'd16) begin\n                        M_x[M_count] <= {5'd0, row_idx};\n                        M_y[M_count] <= {5'd0, col_idx};\n                        M_count <= M_count + 5'd1;\n                    end\n                    else if (current_cell == 2'b10 && S_count < 5'd16) begin\n                        S_x[S_count] <= {5'd0, row_idx};\n                        S_y[S_count] <= {5'd0, col_idx};\n                        S_count <= S_count + 5'd1;\n                    end\n                    \n                    if (col_idx == 3'd7) begin\n                        col_idx <= 3'd0;\n                        if (row_idx == 3'd7) begin\n                            state <= COMPUTE_M;\n                        end else begin\n                            row_idx <= row_idx + 3'd1;\n                        end\n                    end else begin\n                        col_idx <= col_idx + 3'd1;\n                    end\n                end\n                \n                COMPUTE_M: begin\n                    if (M_count <= 5'd1) begin\n                        mirko_spread <= 32'd0;\n                        state <= COMPUTE_S;\n                    end else begin\n                        i_idx <= 5'd0;\n                        j_idx <= 5'd1;\n                        state <= CALC_DIST_M;\n                    end\n                end\n                \n                CALC_DIST_M: begin\n                    mirko_spread <= mirko_spread + dist;\n                    if (j_idx < (M_count - 5'd1)) begin\n                        j_idx <= j_idx + 5'd1;\n                    end\n                    else begin\n                        if (i_idx < (M_count - 5'd2)) begin\n                            i_idx <= i_idx + 5'd1;\n                            j_idx <= i_idx + 5'd2;\n                        end\n                        else begin\n                            state <= COMPUTE_S;\n                        end\n                    end\n                end\n                \n                COMPUTE_S: begin\n                    if (S_count <= 5'd1) begin\n                        slavko_spread <= 32'd0;\n                        state <= DONE;\n                    end else begin\n                        i_idx <= 5'd0;\n                        j_idx <= 5'd1;\n                        state <= CALC_DIST_S;\n                    end\n                end\n                \n                CALC_DIST_S: begin\n                    slavko_spread <= slavko_spread + dist_s;\n                    if (j_idx < (S_count - 5'd1)) begin\n                        j_idx <= j_idx + 5'd1;\n                    end\n                    else begin\n                        if (i_idx < (S_count - 5'd2)) begin\n                            i_idx <= i_idx + 5'd1;\n                            j_idx <= i_idx + 5'd2;\n                        end\n                        else begin\n                            state <= DONE;\n                        end\n                    end\n                end\n                \n                DONE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n        end\n    end\n\nendmodule